-- Extra fixtures stay in this rollback-only database session.
create function pg_temp.booking(p_action text,p_id uuid,p_time text default '09:00:00',p_expected integer default null,p_key uuid default gen_random_uuid()) returns jsonb language sql as $$
 select api.manage_appointment('1a000000-0000-4000-8000-000000000001',p_action,p_id,
 case when p_action='cancel' then '{}'::jsonb when p_action='create' then current_setting('test.data')::jsonb||jsonb_build_object('starts_at',current_setting('test.day')||'T'||p_time||'-03:00') else jsonb_build_object('starts_at',current_setting('test.day')||'T'||p_time||'-03:00','context_versions',jsonb_build_object('staff',1,'calendar',1,'settings',1,'business',1)) end,p_key,p_expected);
$$;
grant execute on function pg_temp.booking(text,uuid,text,integer,uuid) to authenticated;
set local role authenticated;set local "request.jwt.claim.sub"='0a000000-0000-4000-8000-000000000001';
