select is(jsonb_array_length(api.list_appointments_page('1a000000-0000-4000-8000-000000000001',current_setting('test.day'),1,null,1,current_setting('test.cursor'))->'data'),1,'keyset advances on same-day records');
select throws_ok($$select api.list_appointments_page('1a000000-0000-4000-8000-000000000001',current_setting('test.day'),7,null,1,current_setting('test.cursor'))$$,'PT400','VALIDATION_ERROR','cursor bound to filters');
select ok(not exists(select 1 from jsonb_array_elements(api.schedule_preview_source('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001',current_setting('test.day'),1)->'occupied') v where v ? 'appointment_id' or v ? 'customer_id'),'preview includes UTC busy ranges without customer or appointment identity');
