create function pg_temp.reject_booking_child() returns trigger language plpgsql as $$begin raise exception 'INJECTED_CHILD_FAILURE' using errcode='23514';end;$$;
create trigger fixture_fail before insert on public.appointment_events for each row execute function pg_temp.reject_booking_child();
set local role authenticated;
select throws_ok($$select pg_temp.booking('create','7a000000-0000-4000-8000-000000000004','14:00:00')$$,'23514','INJECTED_CHILD_FAILURE','event failure rolls back entire command');
reset role;drop trigger fixture_fail on public.appointment_events;
