select is((select count(*) from app.appointment_occupancy where appointment_id='7a000000-0000-4000-8000-000000000004'),0::bigint,'no partial allocation after injected failures');
select is((select count(*) from public.appointment_events where appointment_id='7a000000-0000-4000-8000-000000000004'),0::bigint,'no partial event after injected failures');
select is((select count(*) from app.appointment_outbox where appointment_id='7a000000-0000-4000-8000-000000000004'),0::bigint,'no partial outbox after injected failures');
select is((select count(*) from app.appointment_requests where result->>'id'='7a000000-0000-4000-8000-000000000004'),0::bigint,'no partial replay after injected failures');
update public.services set name='Renamed catalogue',price_cents=999900,duration_minutes=120,buffer_minutes=60 where id='5a000000-0000-4000-8000-000000000001';
