reset role;
-- Deferred guards catch incomplete direct-maintenance changes too.
create function pg_temp.invalid_release() returns void language plpgsql as $$begin
 update app.appointment_occupancy set released_at=clock_timestamp() where appointment_id='7a000000-0000-4000-8000-000000000002' and released_at is null;
 set constraints all immediate;
end;$$;
select throws_ok('select pg_temp.invalid_release()','PT409','APPOINTMENT_OCCUPANCY_INVALID','commit boundary rejects confirmed booking without allocation');
select is((select count(*) from app.appointment_occupancy where appointment_id='7a000000-0000-4000-8000-000000000002' and released_at is null),1::bigint,'invalid deferred change rolled back');
select throws_ok($$update app.appointment_occupancy set starts_at=starts_at+interval '1 minute' where appointment_id='7a000000-0000-4000-8000-000000000002' and released_at is null$$,'PT409','IMMUTABLE_OCCUPANCY','allocation geometry cannot be rewritten');
select throws_ok($$update public.appointment_events set reason='rewrite' where appointment_id='7a000000-0000-4000-8000-000000000002'$$,'23514','Audit records are immutable','event history immutable');
update public.customers set deleted_at=clock_timestamp() where id='4a000000-0000-4000-8000-000000000001';
update public.services set active=false,deleted_at=clock_timestamp() where id='5a000000-0000-4000-8000-000000000001';
set local role authenticated;
