select throws_ok($$select pg_temp.booking('cancel','7a000000-0000-4000-8000-000000000002',null,3)$$,'PT409','APPOINTMENT_STATE_CONFLICT','new cancel intent cannot mutate already cancelled booking');
reset role;
update app.appointment_requests set created_at=clock_timestamp()-interval '49 hours' where business_id='1a000000-0000-4000-8000-000000000001';
select ok(app.purge_appointment_requests(500)>0,'private maintenance purges expired replays');
