select ok(exists(select 1 from public.appointments where id='7a000000-0000-4000-8000-000000000002'),'purge preserves appointments');
set local role authenticated;
select throws_ok($$select pg_temp.booking('create','7a000000-0000-4000-8000-000000000002')$$,'PT409','DUPLICATE_RESOURCE','expired key cannot create the same stable appointment twice');
reset role;
set constraints all immediate;
select pass('all successful operations satisfy deferred coherence');
set constraints all deferred;
create function pg_temp.invalid_cancel() returns void language plpgsql as $$begin
 update public.appointments set status='cancelled' where id='7a000000-0000-4000-8000-000000000003';set constraints all immediate;
end;$$;
