create function pg_temp.direct_booking(p_id uuid,p_staff uuid,p_start timestamptz) returns void language plpgsql as $$begin
 insert into public.appointments(id,business_id,customer_id,staff_member_id,service_id,starts_at,ends_at,blocked_until,service_name_snapshot,price_cents_snapshot,duration_minutes_snapshot,buffer_minutes_snapshot,created_by) values(p_id,'1a000000-0000-4000-8000-000000000001','4a000000-0000-4000-8000-000000000001',p_staff,'5a000000-0000-4000-8000-000000000001',p_start,p_start,p_start,'Fixture',123400,30,15,'0a000000-0000-4000-8000-000000000001');
 insert into app.appointment_occupancy(business_id,appointment_id,staff_member_id,generation,starts_at,blocked_until) select business_id,id,staff_member_id,1,starts_at,blocked_until from public.appointments where id=p_id;
end;$$;
insert into public.staff_members(id,business_id,display_name) values('3a000000-0000-4000-8000-000000000002','1a000000-0000-4000-8000-000000000001','Independent staff fixture');
