select throws_ok($$select api.write_schedule('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','block',gen_random_uuid(),'save',jsonb_build_object('start_date',current_setting('test.day'),'start_minute',585,'end_date',current_setting('test.day'),'end_minute',600,'kind','manual'),gen_random_uuid(),1)$$,'PT409','APPOINTMENTS_AFFECTED','new time block cannot invalidate a booking');
select throws_ok($$select api.write_schedule('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','plan',gen_random_uuid(),'save',jsonb_build_object('effective_from',current_setting('test.day'),'intervals','[]'::jsonb),gen_random_uuid(),1)$$,'PT409','APPOINTMENTS_AFFECTED','empty weekly revision cannot invalidate a booking');
